style.css:
@-moz-document domain("facebook.com") {
/* ===== 1. Font ===== */
    * {
        font-family: "Monotype Corsiva", cursive !important;
    }

    /* ===== 2. Background ===== */
    body::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background-image: url("https://i.postimg.cc/DZxqnSLg/764a0a214cd8d077fce61134b25bfee5.jpg");
        background-size: cover;
        background-position: center;
        opacity: 0.08;
        z-index: -1;
        pointer-events: none;
    }

    /* ===== 3. Header Character Icon ===== */
    [role="banner"]::after {
        content: '';
        position: absolute;
        top: 5px;
        right: 60px;
        width: 50px;
        height: 50px;
        background-image: url("https://i.postimg.cc/j2WJTZsx/430861.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        pointer-events: none;
        z-index: 9999;
    }

    /* ===== 4. Like Button Character ===== */
    [aria-label="Like"]::after {
        content: '';
        display: inline-block;
        width: 24px;
        height: 24px;
        background-image: url("https://i.postimg.cc/NFrLSF4L/6b6f04eececcf6fdee35b67c4079c0e7.jpg");
        background-size: cover;
        margin-left: 4px;
        vertical-align: middle;
    }

    /* ===== 5. Sidebar Character (bottom left) ===== */
    [role="complementary"]::after {
        content: '';
        display: block;
        width: 80px;
        height: 80px;
        background-image: url("https://i.postimg.cc/cJ4Rj78H/8181571cc55945b53fc2e26121dd2a52.png");
        background-size: contain;
        background-repeat: no-repeat;
        margin: 20px auto;
        border: 2px solid #1c7fff; /* ขอบสีฟ้า */
        border-radius: 10px;
    }

    /* ===== 6. Chat Sidebar Character (bottom right) ===== */
    [aria-label="Chats"]::after {
        content: '';
        position: absolute;
        bottom: 40px;
        right: 10px;
        width: 60px;
        height: 60px;
        background-image: url("https://i.postimg.cc/15qNYCCM/message-Image-1739882637472.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 9999;
        pointer-events: none;
        border: 2px solid #1c7fff; /* ขอบสีฟ้า */
        border-radius: 12px;
    }

    /* ===== 7. Dark Theme Colors ===== */
    body, .x1n2onr6, .x1e56ztr {
        background-color: #001a33 !important;
        color: #e0f7ff !important;
    }

    a, button, .x1i10hfl {
        color: #ffd700 !important; /* สีทอง */
        text-shadow: 0 0 6px #1c7fff; /* ขอบฟ้าอ่อน ๆ ให้ดูเด่น */
        transition: color 0.3s ease, text-shadow 0.3s ease;
    }

    a:hover, button:hover, .x1i10hfl:hover,
    a:focus, button:focus, .x1i10hfl:focus {
        color: #1c7fff !important; /* สีฟ้าเวลาชี้ */
        text-shadow: 0 0 10px #ffd700; /* สีทองเรืองแสงเวลาชี้ */
    }

    /* ===== 8. Scrollbars and Buttons (gold + blue accent) ===== */
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(135deg, #ffd700, #1c7fff) !important;
        border-radius: 10px;
    }

    ::selection {
        background: #1c3aa9 !important;
        color: white;
    }
}
